PHOTO = ''
import base64
import sqlite3
from pathlib import Path
from datetime import datetime, timezone
from django.conf import settings
from django.db import connection, transaction
from main.models import Product

root = Path(settings.BASE_DIR)
backup_dir = root / 'recovery_backups' / datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
backup_dir.mkdir(parents=True, exist_ok=False)
if connection.vendor != 'sqlite':
    raise RuntimeError('Expected the current SQLite database')
connection.ensure_connection()
backup = sqlite3.connect(str(backup_dir / 'db.sqlite3'))
try:
    connection.connection.backup(backup)
finally:
    backup.close()
asset = root / 'main/static/recovered-catalog/dock-station.jpg'
asset.parent.mkdir(parents=True, exist_ok=True)
content = base64.b64decode(PHOTO, validate=True)
if asset.exists() and asset.read_bytes() != content:
    raise RuntimeError('Existing photo differs; refusing to replace it')
asset.write_bytes(content)
with transaction.atomic():
    count = Product.objects.filter(slug__in=['recovered-12', 'recovered-13'], image__in=['',None], image_url__in=['/static/recovered-catalog/no-photo.svg','/static/recovered-catalog/dock-station.jpg']).update(image_url='/static/recovered-catalog/dock-station.jpg')
print('Dock station cards updated:', count)
print('Backup:', backup_dir / 'db.sqlite3')
print('Restart the existing container, then refresh the catalog.')
